SELECT end_user_id,integration_id FROM nw_runtime_host_owners
WHERE tenant_id=#{owner.sessionRef.tenantId.value} AND target_kind=#{owner.target.kind}
  AND target_id=#{owner.target.id} AND agent_id=#{owner.target.id} AND session_id=#{owner.sessionRef.sessionId}

SELECT tenant_id,session_id,agent_id,end_user_id,input_id,generation,source_data::text AS source_data,created_at
FROM nw_system_agent_runtime_capability_sources
WHERE tenant_id=#{owner.sessionRef.tenantId.value} AND session_id=#{owner.sessionRef.sessionId}
  AND agent_id=#{owner.target.id} AND input_id=#{input}
